"""Offline turn announcements generated by Windows Speech API on the Reception PC.

The TV receives a plain WAV, so legacy WebView does not need speechSynthesis.
No external services, personal information, or clinical records are used.
"""
from __future__ import annotations

import base64
import os
import subprocess
import tempfile
import threading
from functools import lru_cache
from pathlib import Path

_speech_lock = threading.Lock()


@lru_cache(maxsize=128)
def _synthesize(turn: int, exam_review: bool) -> bytes | None:
    if os.name != "nt":
        return None
    handle, filename = tempfile.mkstemp(prefix="dr_revelo_turn_", suffix=".wav")
    os.close(handle)
    path = Path(filename)
    try:
        phrase = (
            f"Turno número {turn}, revisión de exámenes. Por favor pasar al consultorio."
            if exam_review
            else f"Turno número {turn}, por favor pasar a consulta."
        )
        escaped_path = str(path).replace("'", "''")
        escaped_phrase = phrase.replace("'", "''")
        script = (
            "$ErrorActionPreference='Stop'\n"
            "Add-Type -AssemblyName System.Speech\n"
            "$speaker=New-Object System.Speech.Synthesis.SpeechSynthesizer\n"
            "try {\n"
            "  $spanish=@($speaker.GetInstalledVoices() | Where-Object { $_.Enabled -and $_.VoiceInfo.Culture.Name -like 'es-*' })\n"
            "  if ($spanish.Count -gt 0) { $speaker.SelectVoice($spanish[0].VoiceInfo.Name) }\n"
            f"  $speaker.SetOutputToWaveFile('{escaped_path}')\n"
            f"  $speaker.Speak('{escaped_phrase}')\n"
            "  $speaker.SetOutputToNull()\n"
            "} finally { $speaker.Dispose() }\n"
        )
        command = base64.b64encode(script.encode("utf-16le")).decode("ascii")
        creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        result = subprocess.run(
            ["powershell.exe", "-NoLogo", "-NoProfile", "-NonInteractive",
             "-EncodedCommand", command],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            timeout=12,
            check=False,
            creationflags=creationflags,
        )
        if result.returncode != 0:
            return None
        data = path.read_bytes()
        if len(data) < 1000 or not data.startswith(b"RIFF") or data[8:12] != b"WAVE":
            return None
        return data
    except (OSError, subprocess.SubprocessError):
        return None
    finally:
        try:
            path.unlink(missing_ok=True)
        except OSError:
            pass


def turn_voice_wav(turn: int, exam_review: bool = False) -> bytes | None:
    """Only a turn number and the consultation/review type reach the synthesizer."""
    if not 1 <= turn <= 999:
        return None
    with _speech_lock:
        return _synthesize(int(turn), bool(exam_review))
